package main

import (
	"crypto/rand"
	"encoding/hex"
	"fmt"
	"net/http"
	"os"
	"path/filepath"
	"strings"

	"github.com/gin-gonic/gin"
)

var uploadDir = os.Getenv("UPLOAD_DIR")

func init() {
	if uploadDir == "" {
		uploadDir = "/var/www/uploads"
	}
}

func generateRandomName() string {
	bytes := make([]byte, 16)
	rand.Read(bytes)
	return hex.EncodeToString(bytes)
}

func sanitizeFilename(name string) string {
	// Remove path traversal attempts
	name = filepath.Base(name)
	// Remove null bytes
	name = strings.ReplaceAll(name, "\x00", "")
	return name
}

func uploadHandler(c *gin.Context) {
	file, err := c.FormFile("document")
	if err != nil {
		c.JSON(http.StatusBadRequest, gin.H{"error": "No file provided"})
		return
	}

	// Size limit: 50MB
	if file.Size > 50*1024*1024 {
		c.JSON(http.StatusBadRequest, gin.H{"error": "File too large"})
		return
	}

	originalName := sanitizeFilename(file.Filename)
	ext := filepath.Ext(originalName)

	// Note: we preserve original extension for user convenience
	// The application relies on infrastructure-level controls for execution prevention
	newName := generateRandomName() + ext

	destPath := filepath.Join(uploadDir, newName)

	if err := c.SaveUploadedFile(file, destPath); err != nil {
		c.JSON(http.StatusInternalServerError, gin.H{"error": "Failed to save file"})
		return
	}

	// Store metadata in S3 for indexing
	s3Key := fmt.Sprintf("metadata/%s.json", newName)
	metadata := fmt.Sprintf(`{"original_name":"%s","size":%d,"s3_key":"%s"}`,
		originalName, file.Size, s3Key)

	// Upload metadata to S3 bucket
	if err := uploadToS3(os.Getenv("METADATA_BUCKET"), s3Key, metadata); err != nil {
		// Non-fatal: file is saved locally, metadata upload is best-effort
		fmt.Printf("Warning: metadata upload failed: %v\n", err)
	}

	c.JSON(http.StatusOK, gin.H{
		"message":  "File uploaded successfully",
		"filename": newName,
		"url":      fmt.Sprintf("/files/%s", newName),
	})
}

func uploadToS3(bucket, key, content string) error {
	// Uses default credential chain (instance role / ECS task role)
	// Requires s3:PutObject permission on the metadata bucket
	// Implementation uses AWS SDK - simplified here
	if bucket == "" {
		return fmt.Errorf("METADATA_BUCKET not configured")
	}
	// aws sdk call would go here
	return nil
