func listHandler(c *gin.Context) {
	entries, err := os.ReadDir(uploadDir)
	if err != nil {
		c.JSON(http.StatusInternalServerError, gin.H{"error": "Cannot list files"})
		return
	}

	var files []gin.H
	for _, entry := range entries {
		if !entry.IsDir() {
			info, _ := entry.Info()
			files = append(files, gin.H{
				"name": entry.Name(),
				"size": info.Size(),
				"url":  fmt.Sprintf("/files/%s", entry.Name()),
			})
		}
	}

	c.JSON(http.StatusOK, gin.H{"files": files})
}

func main() {
	r := gin.Default()

	r.MaxMultipartMemory = 50 << 20 // 50 MB

	r.POST("/api/upload", uploadHandler)
	r.GET("/api/files", listHandler)
	r.Static("/files", uploadDir)

	r.Run(":8080")
}
